<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class NotificationProviderHealthDashboard {
 public static function register(): void { add_action('admin_menu',[self::class,'menu']); }
 public static function menu(): void { add_submenu_page('options-general.php','Provider Health','Provider Health','manage_options','avanik-provider-health',[self::class,'render']); }
 public static function render(): void { if(!current_user_can('manage_options'))return; $providers=NotificationProviderSettings::get(); $logs=[]; if(class_exists(NotificationProviderTestLog::class)&&method_exists(NotificationProviderTestLog::class,'recent'))$logs=NotificationProviderTestLog::recent(100); $latest=[]; foreach((array)$logs as $log){$id=(string)($log['provider']??$log['provider_id']??'');if($id!==''&&!isset($latest[$id]))$latest[$id]=$log;} echo '<div class="wrap" dir="rtl"><h1>سلامت Providerهای اعلان</h1><p>وضعیت تنظیمات، تست اتصال و آخرین نتیجه هر Provider.</p><table class="widefat striped"><thead><tr><th>Provider</th><th>Channel</th><th>وضعیت تنظیمات</th><th>Credentials</th><th>آخرین تست</th><th>زمان پاسخ</th></tr></thead><tbody>'; foreach($providers as $id=>$p){$id=(string)$id;$channels=implode(', ',(array)($p['channels']??[]));$enabled=!empty($p['enabled']);$has=NotificationCredentialVault::has($id);$log=$latest[$id]??[];$ok=($log['result']??$log['status']??'')==='success';$status=$enabled?'فعال':'غیرفعال';$test=$log?($ok?'موفق':'ناموفق'):'تست نشده';$duration=isset($log['duration_ms'])?(int)$log['duration_ms'].' ms':'—';echo '<tr><td><strong>'.esc_html($p['name']??$id).'</strong><br><code>'.esc_html($id).'</code></td><td>'.esc_html($channels?:'—').'</td><td>'.esc_html($status).'</td><td>'.($has?'✓':'—').'</td><td>'.esc_html($test).'</td><td>'.esc_html($duration).'</td></tr>';} if(!$providers)echo '<tr><td colspan="6">Providerی تعریف نشده است.</td></tr>'; echo '</tbody></table></div>'; }
}